import pandas as pd
import numpy as np

file_path = '/data/programme_monthly_spend.xlsx'
df_raw = pd.read_excel(file_path, sheet_name='Monthly Spend', header=None)

# Identify data rows: Programme Code column is 0, starts with PRG-
# Aug 2025 column is 8 (0-indexed)
# Let's collect rows where col0 is string starting with PRG-
rows = []
for i in range(len(df_raw)):
    code = df_raw.iat[i,0]
    if isinstance(code, str) and code.startswith('PRG-'):
        aug_val = df_raw.iat[i,8]
        rows.append((code, aug_val))

print("Found", len(rows), "programme rows")
# Clean aug values
def is_positive(val):
    if pd.isna(val):
        return False
    if isinstance(val, str):
        v = val.strip()
        if v in ('', '-', '–', '—'):
            return False
        # try convert
        try:
            num = float(v.replace(',', ''))
            return num > 0
        except:
            return False
    # numeric
    try:
        return float(val) > 0
    except:
        return False

positive_count = 0
details = []
for code, aug in rows:
    pos = is_positive(aug)
    details.append((code, aug, pos))
    if pos:
        positive_count += 1

for d in details:
    print(d)
print("Positive count:", positive_count)
